)

func TestSupportedWindows(t *testing.T) {
	if err := Supported(); err != nil {
		t.Fatalf("Supported() = %v, want nil (iphlpapi echo procs must resolve)", err)
	}
}

// TestEchoReplyLayout pins the mirror structs to the Windows SDK layout
