	invalidIcmpFile  = ^uintptr(0)
	echoEntryPoints  = []*windows.LazyProc{procCreateFile, procSendEcho2, procCloseHandle}
)

// ipOptionInformation mirrors IP_OPTION_INFORMATION (ipexport.h).
type ipOptionInformation struct {
	Ttl         uint8
	Tos         uint8
	Flags       uint8
	OptionsSize uint8
	OptionsData unsafe.Pointer
}

// icmpEchoReply mirrors ICMP_ECHO_REPLY (ipexport.h).
type icmpEchoReply struct {
	Address       uint32
	Status        uint32
	RoundTripTime uint32
	DataSize      uint16
	Reserved      uint16
	Data          unsafe.Pointer
	Options       ipOptionInformation
}

